import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long n = scanner.nextLong();
        long[] a = new long[16];
        a[0] = 1;
        for (int i = 1; i < 16; i++) {
            a[i] = a[i - 1] * 10 + 1;
        }

        System.out.println(solve(n, 15, a));
        scanner.close();
    }

    private static long solve(long n, int step, long[] a) {
        long ans = (long)(step + 1) * (n / a[step]);
        n %= a[step];
        if (n == 0) {
            return ans;
        }
        long res1 = solve(n, step - 1, a);
        long res2 = step + 1 + solve(a[step] - n, step - 1, a);
        return ans + Math.min(res1, res2);
    }
}
